import java.util.*;

class Solution {
    int[] nums;
    List<Integer>[] graph;
    int[] ans;
    // For each value from 1 to 50, store a stack of pairs (node, depth)
    // representing the ancestors with that value currently in the path.
    Deque<int[]>[] stacks = new Deque[51];

    public int[] getCoprimes(int[] nums, int[][] edges) {
        int n = nums.length;
        this.nums = nums;
        ans = new int[n];
        Arrays.fill(ans, -1);

        graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            graph[e[0]].add(e[1]);
            graph[e[1]].add(e[0]);
        }

        for (int i = 1; i <= 50; i++) {
            stacks[i] = new ArrayDeque<>();
        }

        dfs(0, -1, 0);
        return ans;
    }

    private void dfs(int node, int parent, int depth) {
        int val = nums[node];

        // Find nearest ancestor with coprime value
        int nearestAncestor = -1;
        int nearestDepth = -1;
        for (int v = 1; v <= 50; v++) {
            if (gcd(val, v) == 1 && !stacks[v].isEmpty()) {
                int[] top = stacks[v].peek();
                if (top[1] > nearestDepth) {
                    nearestDepth = top[1];
                    nearestAncestor = top[0];
                }
            }
        }
        ans[node] = nearestAncestor;

        // Add current node to stack of its value
        stacks[val].push(new int[]{node, depth});

        for (int nxt : graph[node]) {
            if (nxt != parent) {
                dfs(nxt, node, depth + 1);
            }
        }

        // Remove current node from stack before backtracking
        stacks[val].pop();
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int t = b;
            b = a % b;
            a = t;
        }
        return a;
    }
}

